+  FAR const char *device_id = vg_identity_get()->device_id;
+  uint64_t hash = 1469598103934665603ull ^ vg_uptime_ms();
+
+  while (*device_id != '\0')
+    {
+      hash ^= (uint8_t)*device_id++;
+      hash *= 1099511628211ull;
+    }
+
+  return hash ^ g_startup.ts_ms;
+}
